import React, { useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { Mail, Pencil, Phone, Plus, Search, ShieldCheck, UserCog, Users } from 'lucide-react';
import { useAdmin } from '../lib/store';
import { Avatar, Badge, EmptyState, Modal, PageHeader, StatCard, cn } from '../lib/ui';
import { type StaffMember } from '../lib/mock';

const emptyStaff = (): StaffMember => ({
  id: `s${Date.now()}`,
  name: '',
  role: 'operator',
  department: 'Buyurtmalar',
  email: '',
  phone: '',
  hired: new Date().toISOString().slice(0, 10),
  active: true,
  emoji: '🧑‍💼',
});

export const Staff = () => {
  const { t } = useTranslation();
  const { staff, saveStaff, notify } = useAdmin();
  const [query, setQuery] = useState('');
  const [role, setRole] = useState('all');
  const [modalOpen, setModalOpen] = useState(false);
  const [editing, setEditing] = useState<StaffMember | null>(null);
  const [draft, setDraft] = useState<StaffMember>(emptyStaff());

  const filtered = useMemo(() => {
    let list = [...staff];
    const q = query.trim().toLowerCase();
    if (q) list = list.filter((s) => `${s.name} ${s.email} ${s.phone}`.toLowerCase().includes(q));
    if (role !== 'all') list = list.filter((s) => s.role === role);
    return list;
  }, [staff, query, role]);

  const openCreate = () => {
    setEditing(null);
    setDraft(emptyStaff());
    setModalOpen(true);
  };

  const openEdit = (s: StaffMember) => {
    setEditing(s);
    setDraft({ ...s });
    setModalOpen(true);
  };

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!draft.name.trim()) {
      notify('Ismni kiriting', 'error');
      return;
    }
    const emoji = draft.role === 'courier' ? '🧑‍✈️' : draft.role === 'manager' ? '👨‍💼' : '👩‍💼';
    saveStaff({ ...draft, emoji });
    notify(editing ? t('updated') : t('created'));
    setModalOpen(false);
  };

  const toggleActive = (s: StaffMember) => {
    saveStaff({ ...s, active: !s.active });
    notify(s.active ? 'Xodim nofaol qilindi' : 'Xodim faollashtirildi');
  };

  return (
    <div className="animate-fade-up">
      <PageHeader
        title={t('staffTitle')}
        subtitle={t('staffSubtitle')}
        action={<button className="btn-primary btn-sm" onClick={openCreate}><Plus size={16} /> {t('addStaff')}</button>}
      />

      <div className="mb-5 grid grid-cols-1 gap-4 sm:grid-cols-2 xl:grid-cols-4">
        <StatCard label="Jami xodimlar" value={String(staff.length)} icon={<Users size={20} />} />
        <StatCard label={t('active')} value={String(staff.filter((s) => s.active).length)} icon={<ShieldCheck size={20} />} tone="sky" />
        <StatCard label={t('manager')} value={String(staff.filter((s) => s.role === 'manager').length)} icon={<UserCog size={20} />} tone="violet" />
        <StatCard label={t('courier')} value={String(staff.filter((s) => s.role === 'courier').length)} icon={<span className="text-lg">🛵</span>} tone="amber" />
      </div>

      <div className="card p-4 sm:p-5">
        <div className="mb-4 flex flex-col gap-2 sm:flex-row">
          <div className="relative flex-1">
            <Search size={17} className="absolute left-3.5 top-1/2 -translate-y-1/2 text-[var(--muted)]" />
            <input className="input pl-10" placeholder="Xodim qidirish..." value={query} onChange={(e) => setQuery(e.target.value)} />
          </div>
          <select className="select sm:w-44" value={role} onChange={(e) => setRole(e.target.value)}>
            <option value="all">{t('all')}</option>
            <option value="manager">{t('manager')}</option>
            <option value="operator">{t('operator')}</option>
            <option value="courier">{t('courier')}</option>
          </select>
        </div>

        {filtered.length === 0 ? (
          <EmptyState title={t('noData')} />
        ) : (
          <div className="table-wrap">
            <table className="data-table">
              <thead>
                <tr>
                  <th>{t('name')}</th>
                  <th>{t('role')}</th>
                  <th>{t('department')}</th>
                  <th>{t('email')}</th>
                  <th>{t('phone')}</th>
                  <th>{t('hired')}</th>
                  <th>{t('status')}</th>
                  <th className="text-right">{t('actions')}</th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((s) => (
                  <tr key={s.id} className={cn(!s.active && 'opacity-60')}>
                    <td>
                      <div className="flex items-center gap-2.5">
                        <Avatar emoji={s.emoji} size="sm" />
                        <p className="text-xs font-extrabold">{s.name}</p>
                      </div>
                    </td>
                    <td><Badge tone={s.role === 'manager' ? 'violet' : s.role === 'courier' ? 'warning' : 'info'}>{t(s.role)}</Badge></td>
                    <td className="text-xs text-[var(--muted)]">{s.department}</td>
                    <td className="text-xs"><span className="flex items-center gap-1"><Mail size={11} /> {s.email}</span></td>
                    <td className="text-xs"><span className="flex items-center gap-1"><Phone size={11} /> {s.phone}</span></td>
                    <td className="text-xs text-[var(--muted)]">{s.hired}</td>
                    <td><Badge tone={s.active ? 'success' : 'neutral'}>{s.active ? t('active') : t('inactive')}</Badge></td>
                    <td>
                      <div className="flex justify-end gap-1">
                        <button className="icon-btn h-8 w-8" onClick={() => openEdit(s)}><Pencil size={13} /></button>
                        <button className="btn-secondary btn-sm" onClick={() => toggleActive(s)}>{s.active ? 'Nofaol' : 'Faol'}</button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      <Modal open={modalOpen} onClose={() => setModalOpen(false)} title={editing ? t('edit') : t('addStaff')}>
        <form onSubmit={submit} className="space-y-4">
          <div>
            <label className="label">{t('name')}</label>
            <input className="input" value={draft.name} onChange={(e) => setDraft({ ...draft, name: e.target.value })} placeholder="Ism familiya" />
          </div>
          <div className="grid grid-cols-2 gap-3">
            <div>
              <label className="label">{t('role')}</label>
              <select className="select" value={draft.role} onChange={(e) => setDraft({ ...draft, role: e.target.value as StaffMember['role'] })}>
                <option value="manager">{t('manager')}</option>
                <option value="operator">{t('operator')}</option>
                <option value="courier">{t('courier')}</option>
              </select>
            </div>
            <div>
              <label className="label">{t('department')}</label>
              <input className="input" value={draft.department} onChange={(e) => setDraft({ ...draft, department: e.target.value })} />
            </div>
            <div>
              <label className="label">{t('email')}</label>
              <input type="email" className="input" value={draft.email} onChange={(e) => setDraft({ ...draft, email: e.target.value })} />
            </div>
            <div>
              <label className="label">{t('phone')}</label>
              <input className="input" value={draft.phone} onChange={(e) => setDraft({ ...draft, phone: e.target.value })} />
            </div>
            <div>
              <label className="label">{t('hired')}</label>
              <input type="date" className="input" value={draft.hired} onChange={(e) => setDraft({ ...draft, hired: e.target.value })} />
            </div>
            <div>
              <label className="label">{t('status')}</label>
              <select className="select" value={draft.active ? 'active' : 'inactive'} onChange={(e) => setDraft({ ...draft, active: e.target.value === 'active' })}>
                <option value="active">{t('active')}</option>
                <option value="inactive">{t('inactive')}</option>
              </select>
            </div>
          </div>
          <div className="flex gap-2">
            <button type="button" className="btn-secondary flex-1" onClick={() => setModalOpen(false)}>{t('cancel')}</button>
            <button type="submit" className="btn-primary flex-1">{t('save')}</button>
          </div>
        </form>
      </Modal>
    </div>
  );
};
